const state = document.getElementById('state');
const refresh = document.getElementById('refresh');

refresh.addEventListener('click', () => {
  state.innerHTML = '<p>Loading articles...</p>';
  window.setTimeout(() => {
    state.innerHTML = '<div class="empty-icon" aria-hidden="true">✦</div><h2>No articles yet</h2><p>Start your collection by creating the first article.</p><button id="create" class="primary" type="button">Create article</button>';
    state.querySelector('#create').focus();
  }, 400);
});

state.addEventListener('click', (event) => {
  if (event.target.id === 'create') {
    state.querySelector('p').textContent = 'The article editor would open here.';
  }
});
